// src/projectConfig.ts
import { registerConfigNormalizer } from "@holo-js/config/registry";
function normalizeMediaConfig(config = {}) {
  return Object.freeze({ ...config });
}
function defineMediaConfig(config) {
  return Object.freeze({ ...config });
}
registerConfigNormalizer({
  name: "media",
  normalize: normalizeMediaConfig
});

export {
  normalizeMediaConfig,
  defineMediaConfig
};
